-- ----------------------------------------------------------------------------------------------------------------
-- Benutzer                (UserType 0=User 1=System-Administrator 2=Systemuser)
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdUsers (
	ID AUTOINC NOT NULL,
  UserType INTEGER DEFAULT 0,
	Name VARCHAR(50) NOT NULL,
	Fullname VARCHAR(150),
	Description VARCHAR(255),
  UserRights VARCHAR(50),
	LoginPassword VARCHAR(255),
  Email VARCHAR(255),
	Picture BLOB,
  ActiveDirectorySID VARCHAR(255),
  ActiveDirectoryAuth BOOLEAN,
  ActiveDirectoryAutoLogin BOOLEAN,
  LocalSID VARCHAR(255),
  CanDoWindowsLogon BOOLEAN,
  LastPasswordChange DATETIME,
  BadPasswordCount INTEGER,
  PasswordExpired DATETIME,
  LastLogin DATETIME,
  LastIP VARCHAR(255),
  LogonCount INTEGER,
  AccountExpires DATETIME,
	MustChangePwd BOOLEAN,
	CanNotChangePwd BOOLEAN,
	PwdDontExpires BOOLEAN,
	Inactive BOOLEAN DEFAULT FALSE,
  Deleted BOOLEAN NOT NULL DEFAULT FALSE,
  CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID)
);

INSERT INTO tdUsers (ID, Name, Fullname, Description, LoginPassword, MustChangePwd, UserType, UserRights, CreationUserID, CreationDate, ChangeUserID, ChangeDate) VALUES (1, 'Administrator', 'Administrator', 'Vordefiniertes Konto für die Verwaltung der Passwortdatenbank', '21232f297a57a5a743894a0e4a801fc3', TRUE, 1, '11111111111111111111', 1, TODATE('1/1/2008 0:0:0:0','M/D/YYYY H24:N:S:Z'), 1, TODATE('1/1/2008 0:0:0:0','M/D/YYYY H24:N:S:Z'));

-- ----------------------------------------------------------------------------------------------------------------
-- Gruppen             (GroupType 0=Group 1=System-Administratoren 2=System-Nachrichten 3=System-Aufgaben)
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdGroups (
	ID AUTOINC NOT NULL,
  GroupType INTEGER DEFAULT 0,
	Name VARCHAR(50) NOT NULL,
	Description VARCHAR(255),
  ActiveDirectorySID VARCHAR(255),
	Inactive BOOLEAN DEFAULT FALSE,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID),
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

INSERT INTO tdGroups (ID, Name, Description, GroupType, CreationUserID, CreationDate, ChangeUserID, ChangeDate) VALUES (1, 'Administratoren', 'Vordefiniertes Konto für die Verwaltung der Passwortdatenbank', 1, 1, TODATE('1/1/2008 0:0:0:0','M/D/YYYY H24:N:S:Z'), 1, TODATE('1/1/2008 0:0:0:0','M/D/YYYY H24:N:S:Z'));

-- ----------------------------------------------------------------------------------------------------------------
-- Gruppen-Mitglieder Gruppen
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdGroupMemberGroups (
	GroupID INTEGER NOT NULL,
	MemberGroupID INTEGER NOT NULL,
	PRIMARY KEY PK_ID (GroupID, MemberGroupID),
	FOREIGN KEY FK_GroupID (GroupID)
		REFERENCES tdGroups
			ON DELETE CASCADE,
	FOREIGN KEY FK_MemberGroupID (MemberGroupID)
		REFERENCES tdGroups
			ON DELETE CASCADE
);

-- ----------------------------------------------------------------------------------------------------------------
-- Gruppen-Mitglieder Benutzer
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdGroupMemberUsers (
	GroupID INTEGER NOT NULL,
	MemberUserID INTEGER NOT NULL,
	PRIMARY KEY PK_ID (GroupID, MemberUserID),
	FOREIGN KEY FK_GroupID (GroupID)
		REFERENCES tdGroups
			ON DELETE CASCADE,
	FOREIGN KEY FK_MemberUserID (MemberUserID)
		REFERENCES tdUsers
			ON DELETE CASCADE
);

INSERT INTO tdGroupMemberUsers (GroupID, MemberUserID) VALUES (1, 1);

-- ----------------------------------------------------------------------------------------------------------------
-- Icons für Ordner, Datensätze, usw.
-- IconType: 0=BuildIn, 1=Custom
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdIcons (
	ID AUTOINC NOT NULL,
	Name VARCHAR(50),
	IconType INTEGER NOT NULL DEFAULT 0,
	IconData16 BLOB,
  IconData32 BLOB,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID),
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

