-- ----------------------------------------------------------------------------------------------------------------
-- Formulare
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdForms (
	ID AUTOINC NOT NULL,
	Name VARCHAR(255),
  Content VARCHAR(255),
	Description MEMO,
  FolderIconID INTEGER,
  DataIconID INTEGER,
	PRIMARY KEY PK_ID (ID),
	FOREIGN KEY FK_FolderIconID (FolderIconID)
		REFERENCES tdIcons,
	FOREIGN KEY FK_DataIconID (DataIconID)
		REFERENCES tdIcons
);

