-- ----------------------------------------------------------------------------------------------------------------
-- Formularfelder
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdFormFields (
	ID AUTOINC NOT NULL,
	FormID INTEGER NOT NULL,
	FieldType INTEGER NOT NULL,
	FieldLabel VARCHAR(255) NOT NULL,
  FieldName VARCHAR(50) NOT NULL,
  FieldDesc MEMO,
  FieldDefaultValue VARCHAR(255),
  FieldMandatory BOOLEAN NOT NULL DEFAULT FALSE,
	FieldMinLength INTEGER,
	FieldMaxLength INTEGER,
  FieldAllowedChars VARCHAR(255),
  FieldMask VARCHAR(100),
  FieldItems MEMO,
  FieldItemNames MEMO,
	FieldPosition INTEGER NOT NULL DEFAULT 0,
	FieldShowOnCard BOOLEAN NOT NULL DEFAULT FALSE,
  FieldProtected BOOLEAN NOT NULL DEFAULT FALSE,
  FieldActive BOOLEAN NOT NULL DEFAULT TRUE,
  FieldSortDirection INTEGER NOT NULL DEFAULT 0,
  FieldColumnWidth INTEGER NOT NULL DEFAULT 100,
  FieldIsURL BOOLEAN NOT NULL DEFAULT FALSE,
  FieldIsEmail BOOLEAN NOT NULL DEFAULT FALSE,
	PRIMARY KEY PK_ID (ID),
	FOREIGN KEY FK_FormID (FormID)
		REFERENCES tdForms
			ON DELETE CASCADE
);

CREATE INDEX IDX_FormID ON tdFormFields (
  FormID
);

