-- ----------------------------------------------------------------------------------------------------------------
-- Ordner (Kategorien)
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdFolders (
	ID AUTOINC NOT NULL,
	ParentID INTEGER NOT NULL DEFAULT 0,
	FolderType INTEGER NOT NULL,
	FormID INTEGER,
  FormSelectionType INTEGER NOT NULL DEFAULT 0,
	Name VARCHAR(255),
	Description MEMO,
	IconID INTEGER NOT NULL,
  HtmlURL MEMO,
  HtmlSource MEMO,
  CustomFieldsData MEMO,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID),
	FOREIGN KEY FK_FormID (FormID)
		REFERENCES tdForms,
	FOREIGN KEY FK_IconID (IconID)
		REFERENCES tdIcons,
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

CREATE INDEX IDX_ParentID ON tdFolders (
  ParentID
);

