-- ----------------------------------------------------------------------------------------------------------------
-- Ordner-Favoriten
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdFolderFavorites (
	FolderID INTEGER NOT NULL,
  UserID INTEGER NOT NULL,
	FolderPosition INTEGER NOT NULL DEFAULT 0,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (FolderID, UserID),
	FOREIGN KEY FK_FolderID (FolderID)
		REFERENCES tdFolders
			ON DELETE CASCADE,
	FOREIGN KEY FK_UserID (UserID)
		REFERENCES tdUsers
			ON DELETE CASCADE,
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

-- ----------------------------------------------------------------------------------------------------------------
-- Ordner-Formulare
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdFolderForms (
	FolderID INTEGER NOT NULL,
  FormID INTEGER NOT NULL,
	PRIMARY KEY PK_ID (FolderID, FormID),
	FOREIGN KEY FK_FolderID (FolderID)
		REFERENCES tdFolders
			ON DELETE CASCADE,
	FOREIGN KEY FK_FormID (FormID)
		REFERENCES tdForms
			ON DELETE CASCADE
);

-- ----------------------------------------------------------------------------------------------------------------
-- Ordner-Rechte (Gruppen und Benutzer)
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdFolderRights (
	FolderID INTEGER NOT NULL,
	GroupID INTEGER,
  UserID INTEGER,
	CanRead BOOLEAN NOT NULL DEFAULT FALSE,
	CanWrite BOOLEAN NOT NULL DEFAULT FALSE,
