-- ----------------------------------------------------------------------------------------------------------------
-- Fensterüberwachung
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdApplications (
	ID AUTOINC NOT NULL,
	AppName VARCHAR(255),
	AppComments MEMO,
  AppActive BOOLEAN,
  AppExeName MEMO,
  AppExeNameUseRegExp BOOLEAN NOT NULL DEFAULT FALSE,
  AppWindowText MEMO,
  AppWindowTextUseRegExp BOOLEAN NOT NULL DEFAULT FALSE,
  AppClassName VARCHAR(255),
  AppClassNameUseRegExp BOOLEAN NOT NULL DEFAULT FALSE,
  AppURL MEMO,
  AppURLUseRegExp BOOLEAN NOT NULL DEFAULT FALSE,
  AppEntryType INTEGER,
  AppAutoEntry BOOLEAN,
  AppRepeatCall BOOLEAN,
  AppNeverSameWindow BOOLEAN,
  AppDeactivateWindow BOOLEAN,
  AppCharChoiceUser BOOLEAN,
  AppCharChoicePwd BOOLEAN,
  AppCtrls MEMO,
  AppScript MEMO,
  AppScriptDelay INTEGER,
  AppScriptRandomDelay BOOLEAN,
  AppMacroRecorderFile MEMO,
  AppMacroSpeedFactor INTEGER,
  AppMacroSetWinPos BOOLEAN,
  AppMacroWinPosLeft INTEGER,
  AppMacroWinPosTop INTEGER,
  AppMacroWinPosRight INTEGER,
  AppMacroWinPosBottom INTEGER,
  AppWaitBefore INTEGER,
  AppWaitAfter INTEGER,
  AppWaitAfterQuestion INTEGER,
  AppWindowSelActive BOOLEAN,
  AppWindowSelParams MEMO,
  AppBrowserFields MEMO,
  CustomFieldsData MEMO,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID),
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

-- ----------------------------------------------------------------------------------------------------------------
-- Labels
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdLabels (
	ID AUTOINC NOT NULL,
	Name VARCHAR(255),
	Description MEMO,
  Color INTEGER,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	PRIMARY KEY PK_ID (ID),
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

-- ----------------------------------------------------------------------------------------------------------------
-- Anhang / Dateien      DocumentType 0=Doc, 1=Link (siehe _const.pas)
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdDocuments (
	ID AUTOINC NOT NULL,
	DocumentDesc VARCHAR(255),
	DocumentPath VARCHAR(999),
	DocumentData BLOB BLOBCOMPRESSIONALGORITHM ZLIB BLOBCOMPRESSIONMODE 9,
  DocumentSize INTEGER,
  DocumentType INTEGER,
  DocumentParameters VARCHAR(255),
	ExpirationDate DATETIME,
	ExpirationDays INTEGER,
  Comments MEMO,
  DocumentIcon INTEGER,
  LinkPathStartApp VARCHAR(999),
  DocIDStartApp INTEGER,
  LinkPathEndApp VARCHAR(999),
  DocIDEndApp INTEGER,
  DocumentTmpPath VARCHAR(999),
  WindowMode INTEGER,
  CustomFieldsData MEMO,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	ChangeUserID INTEGER,
	ChangeDate DATETIME,
	ViewUserID INTEGER,
	ViewUserDate DATETIME,
	PRIMARY KEY PK_ID (ID),
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ViewUserID (ViewUserID)
		REFERENCES tdUsers
);

-- ----------------------------------------------------------------------------------------------------------------
-- Anhang / Dateien: History
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdDocumentHistory (
	ID AUTOINC NOT NULL,
	DocumentID INTEGER NOT NULL,
  DocumentData BLOB BLOBCOMPRESSIONALGORITHM ZLIB BLOBCOMPRESSIONMODE 9,
  DocumentSize INTEGER,
	CreationUserID INTEGER,
	CreationDate DATETIME,
	PRIMARY KEY PK_ID (ID, DocumentID),
	FOREIGN KEY FK_DocumentID (DocumentID)
		REFERENCES tdDocuments
			ON DELETE CASCADE,
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers
);

-- ----------------------------------------------------------------------------------------------------------------
-- Datei-Gruppenrechte
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdDocumentRights (
	DocumentID INTEGER NOT NULL,
	GroupID INTEGER,
  UserID INTEGER,
	CanRead BOOLEAN NOT NULL DEFAULT FALSE,
	CanWrite BOOLEAN NOT NULL DEFAULT FALSE,
	CanDelete BOOLEAN NOT NULL DEFAULT FALSE,
	CanMove BOOLEAN NOT NULL DEFAULT FALSE,
	CanPrint BOOLEAN NOT NULL DEFAULT FALSE,
	CanExport BOOLEAN NOT NULL DEFAULT FALSE,
  CanChangeRights BOOLEAN NOT NULL DEFAULT FALSE,
	FOREIGN KEY FK_DocumentID (DocumentID)
		REFERENCES tdDocuments
			ON DELETE CASCADE,
	FOREIGN KEY FK_GroupID (GroupID)
		REFERENCES tdGroups
			ON DELETE CASCADE,
	FOREIGN KEY FK_UserID (UserID)
		REFERENCES tdUsers
			ON DELETE CASCADE
);

CREATE INDEX IDX_ID ON tdDocumentRights (
  DocumentID,
  GroupID,
