		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ViewUserID (ViewUserID)
		REFERENCES tdUsers
);

