-- ----------------------------------------------------------------------------------------------------------------
-- Passwörter: Siegel
-- ----------------------------------------------------------------------------------------------------------------
CREATE TABLE tdPasswordSeals (
	ID AUTOINC NOT NULL,
	PasswordID INTEGER NOT NULL,
	ActivatedUserID INTEGER,
	ActivatedDate DATETIME,
	ActivatedDesc MEMO,
	BrokenUserID INTEGER,
	BrokenDate DATETIME,
	BrokenDesc MEMO,
	DeactivatedUserID INTEGER,
	DeactivatedUserDate DATETIME,
	DecativatedDesc MEMO,
  NumberOfConfirmations INTEGER,
  NumberOfValidConfirmationDays INTEGER,
	IsClosed BOOLEAN NOT NULL DEFAULT FALSE,
