			ON DELETE CASCADE,
	FOREIGN KEY FK_ActivatedUserID (ActivatedUserID)
		REFERENCES tdUsers,
	FOREIGN KEY FK_BrokenUserID (ActivatedUserID)
		REFERENCES tdUsers,
	FOREIGN KEY FK_DeactivatedUserID (DeactivatedUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_RequestUserID (RequestUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_CreationUserID (CreationUserID)
		REFERENCES tdUsers,
  FOREIGN KEY FK_ChangeUserID (ChangeUserID)
		REFERENCES tdUsers
);

